(function(){'use strict';const $=id=>document.getElementById(id);const S={module:'western',cases:[],formulas:[],herbs:[],case:null,patient:null,zhengOk:false,selectedFormula:null,items:[]};const SURNAMES=['张','李','王','赵','刘','陈','杨','黄','周','吴'];const GIVEN_M=['伟','强','军','磊','勇','刚','健','涛'];const GIVEN_F=['芳','娜','敏','静','艳','娟','霞','燕'];function pickPatient(c){const genders=c&&c.gender?[c.gender]:['男','女'];const gender=genders[Math.floor(Math.random()*genders.length)];const sn=SURNAMES[Math.floor(Math.random()*SURNAMES.length)];const gn=gender==='男'?GIVEN_M[Math.floor(Math.random()*GIVEN_M.length)]:GIVEN_F[Math.floor(Math.random()*GIVEN_F.length)];const age=(c&&c.age_range)?Math.floor(c.age_range[0]+Math.random()*(c.age_range[1]-c.age_range[0])):Math.floor(25+Math.random()*45);return{name:sn+gn,gender,age};}
async function loadJSON(url){const r=await fetch(url);if(!r.ok)throw new Error(url+' '+r.status);return r.json();}
async function boot(){try{const[cj,fj,hj,rj]=await Promise.all([loadJSON('data/tcm-cases.json').catch(()=>null),loadJSON('data/tcm-formulas.json').catch(()=>null),loadJSON('data/tcm-herbs.json').catch(()=>null),loadJSON('data/tcm-rules.json').catch(()=>null)]);S.cases=(cj&&cj.cases)||(Array.isArray(cj)?cj:[]);S.formulas=(fj&&fj.formulas)||(Array.isArray(fj)?fj:[]);S.herbs=(hj&&hj.herbs)||(Array.isArray(hj)?hj:[]);if(rj&&rj.rules)window.TCMEngine.extraRules=rj.rules;if(S.cases.length===0){const tip=$('tcm-data-tip');if(tip)tip.classList.remove('hidden');}
renderFormulaOptions();renderHerbList('');}catch(e){console.warn('TCM data load failed:',e);}}
const ALL_VIEWS=['view-home','view-rx','view-report','view-radar','view-mistakes','view-stats','view-drugs','view-tcm-home','view-tcm-case','view-tcm-rx','view-tcm-report','view-acup-home','view-acup-case','view-acup-rx','view-acup-report','view-acup-map','view-anat-home','view-anat-system','view-anat-detail','view-anat-quiz','view-anat-cases'];function showView(id){ALL_VIEWS.forEach(v=>{const el=$(v);if(el)el.classList.add('hidden');});const el=$(id);if(el)el.classList.remove('hidden');window.scrollTo(0,0);}
window.__showView=showView;function setModule(m){S.module=m;window.__currentModule=m;document.querySelectorAll('.module-tab').forEach(t=>{const on=t.getAttribute('data-module')===m;t.classList.toggle('active',on);t.setAttribute('aria-selected',on?'true':'false');});const drugsBtn=document.querySelector('[data-goto="drugs"]');if(drugsBtn)drugsBtn.parentElement.style.display=(m==='western')?'':'none';resetState();if(m==='western')showView('view-home');else if(m==='tcm')showView('view-tcm-home');else if(m==='acup')showView('view-acup-home');else if(m==='anat')showView('view-anat-home');}
window.__setModule=setModule;function resetState(){S.case=null;S.zhengOk=false;S.selectedFormula=null;S.items=[];const ze=$('tcm-zheng-input');if(ze)ze.value='';const zf=$('tcm-zheng-feedback');if(zf)zf.innerHTML='';const fr=$('tcm-fazheng-row');if(fr)fr.classList.add('hidden');const fe=$('tcm-fazheng-input');if(fe)fe.value='';const fd=$('tcm-formula-detail');if(fd)fd.classList.add('hidden');S.items=[];}
function bindTabs(){document.querySelectorAll('.module-tab').forEach(t=>{t.addEventListener('click',()=>setModule(t.getAttribute('data-module')));});document.querySelectorAll('[data-goto="home"]').forEach(btn=>{const orig=btn.onclick;btn.addEventListener('click',function(e){const m=window.__currentModule||'western';if(m==='tcm'){e.stopImmediatePropagation();showView('view-tcm-home');}
else if(m==='acup'){e.stopImmediatePropagation();showView('view-acup-home');}
else if(m==='anat'){e.stopImmediatePropagation();showView('view-anat-home');}},true);});}
function newCase(){if(S.cases.length===0){alert('中医病例数据尚未就绪，请稍候再试（数据文件由并行任务生成中）。');return;}
const diff=document.querySelector('input[name="tcm-diff"]:checked');const d=diff?diff.value:'all';let pool=S.cases;if(d!=='all')pool=pool.filter(c=>c.difficulty===d);if(pool.length===0)pool=S.cases;S.case=pool[Math.floor(Math.random()*pool.length)];S.patient=pickPatient(S.case);S.zhengOk=false;renderCase();showView('view-tcm-case');}
function renderCase(){const c=S.case,p=S.patient;$('tcm-case-diff').textContent=c.difficulty||'初级';$('tcm-case-meta').innerHTML=`患者：${p.name} · ${p.gender} · ${p.age}岁　科别：中医科`;const s=c.symptom_pool||c.symptoms||{};const first=a=>Array.isArray(a)?(a[0]||'-'):(a||'-');$('tcm-case-body').innerHTML=`
      <p><b>【主诉】</b>${first(s.chief_complaint)}</p>
      <p><b>【病史】</b>${first(s.history)}</p>
      <p><b>【舌象】</b>${first(s.tongue)}</p>
      <p><b>【脉象】</b>${first(s.pulse)}</p>
      <p><b>【查体】</b>${first(s.exam)}</p>
    `;const dl=$('tcm-zheng-list');if(dl){const opts=[c.syndrome_differentiation,...(c.differential||[])].filter(Boolean);dl.innerHTML=Array.from(new Set(opts)).map(z=>`<option value="${z}">`).join('');}
$('tcm-zheng-feedback').innerHTML='';$('tcm-fazheng-row').classList.add('hidden');}
function checkZheng(){const input=($('tcm-zheng-input').value||'').trim();if(!input){$('tcm-zheng-feedback').innerHTML='<span style="color:#b91c1c;">请输入证型。</span>';return;}
const ref=(S.case.syndrome_differentiation||'').trim();const ok=input===ref||(ref&&(ref.indexOf(input)>=0||input.indexOf(ref)>=0));if(ok){S.zhengOk=true;$('tcm-zheng-feedback').innerHTML=`<span style="color:#15803d;">✅ 辨证正确：${ref}</span>`;$('tcm-fazheng-row').classList.remove('hidden');if(!$('tcm-fazheng-input').value)$('tcm-fazheng-input').placeholder=S.case.treatment_principle||'';}else{S.zhengOk=false;$('tcm-zheng-feedback').innerHTML=`<span style="color:#b91c1c;">❌ 辨证待斟酌。再结合舌象、脉象想想。</span>`;}}
function openRx(){if(!S.zhengOk){alert('请先确认辨证。');return;}
const p=S.patient;$('tcm-p-name').textContent=p.name;$('tcm-p-gender').textContent=p.gender;$('tcm-p-age').textContent=p.age;$('tcm-p-zheng').textContent=S.case.syndrome_differentiation||'';const fz=($('tcm-fazheng-input').value||'').trim()||S.case.treatment_principle||'';$('tcm-p-fazheng').textContent=fz;$('tcm-p-date').textContent=new Date().toLocaleDateString();$('tcm-rx-no').textContent='TCM-'+Date.now().toString().slice(-6);S.items=[];S.selectedFormula=null;const refCode=(S.case.reference_formula_code||'').toUpperCase();if(refCode){const fm=S.formulas.find(f=>(f.code||'').toUpperCase()===refCode);if(fm)selectFormula(fm,true);}
renderItems();renderFormulaList('');renderHerbList('');showView('view-tcm-rx');}
function renderFormulaOptions(){const sel=$('tcm-formula-select');if(!sel)return;sel.innerHTML='<option value="">— 或直接选择方剂 —</option>'+
S.formulas.map(f=>`<option value="${f.name}">${f.name}（${f.category || ''}）</option>`).join('');}
function renderFormulaList(kw){const list=$('tcm-formula-list');if(!list)return;const k=(kw||'').toLowerCase();const items=S.formulas.filter(f=>!k||f.name.toLowerCase().indexOf(k)>=0||(f.category||'').indexOf(k)>=0);if(items.length===0){list.innerHTML='<div style="padding:10px;color:#94a3b8;">无匹配方剂</div>';return;}
list.innerHTML=items.slice(0,50).map(f=>`
      <div class="tcm-formula-item ${S.selectedFormula && S.selectedFormula.name === f.name ? 'selected' : ''}" data-fm="${f.name}">
        <span><b>${f.name}</b> <small class="muted">${f.category || ''}</small></span>
        <small class="muted">${(f.indications || '').slice(0,30)}</small>
      </div>`).join('');list.querySelectorAll('.tcm-formula-item').forEach(el=>{el.onclick=()=>{const f=S.formulas.find(x=>x.name===el.getAttribute('data-fm'));if(f)selectFormula(f);};});}
function selectFormula(fm,silent){S.selectedFormula=fm;const comp=fm.composition||[];comp.forEach(c=>{const exist=S.items.find(it=>it.name===c.herb);if(exist){exist.dose=c.dose;exist.role=c.role;}
else S.items.push({name:c.herb,dose:c.dose,role:c.role,prep:''});});const detail=$('tcm-formula-detail');detail.classList.remove('hidden');detail.innerHTML=`
      <b>${fm.name}</b>（${fm.source || ''} · ${fm.category || ''}）<br>
      <b>组成：</b>${comp.map(c => `${c.herb}${c.dose}`).join('，')}<br>
      <b>功用：</b>${fm.functions || ''}<br>
      <b>主治：</b>${fm.indications || ''}<br>
      <b>加减：</b>${(fm.modified || []).join('；') || '-'}
    `;renderItems();renderFormulaList($('tcm-formula-search').value);if(!silent)window.__showLoading&&window.__showLoading(200);}
function renderHerbList(kw){const list=$('tcm-herb-list');if(!list)return;const k=(kw||'').toLowerCase();const items=S.herbs.filter(h=>!k||h.name.toLowerCase().indexOf(k)>=0||(h.pinyin||'').indexOf(k)>=0);if(items.length===0){list.innerHTML='<div style="padding:10px;color:#94a3b8;">无匹配中药</div>';return;}
list.innerHTML=items.slice(0,60).map(h=>`
      <div class="tcm-herb-item" data-herb="${h.name}">
        <span><b>${h.name}</b> <small class="muted">${h.nature || ''} ${h.meridian || ''}</small></span>
        <small class="muted">常用 ${h.dose_range || ''}${h.incompatibility && h.incompatibility !== '无' ? ' · ⚠️' : ''}</small>
      </div>`).join('');list.querySelectorAll('.tcm-herb-item').forEach(el=>{el.onclick=()=>{const h=S.herbs.find(x=>x.name===el.getAttribute('data-herb'));if(!h)return;if(S.items.find(it=>it.name===h.name)){alert('已在处方中：'+h.name);return;}
const dr=h.dose_range||'10g';const m=dr.match(/(\d+(?:\.\d+)?)\s*g/);const defaultDose=m?m[1]:'10';S.items.push({name:h.name,dose:defaultDose,role:'佐',prep:''});renderItems();};});}
function renderItems(){const tb=$('tcm-items');$('tcm-herb-count').textContent='已选 '+S.items.length+' 味';if(S.items.length===0){tb.innerHTML='<tr><td colspan="5" style="color:#94a3b8;padding:14px;">请在上方搜索并选择方剂或中药</td></tr>';return;}
tb.innerHTML=S.items.map((it,i)=>`
      <tr>
        <td>${i+1}</td>
        <td><b>${it.name}</b></td>
        <td><input type="number" step="0.5" value="${it.dose.replace(/g.*/,'')}" data-i="${i}" data-k="dose"></td>
        <td>
          <select data-i="${i}" data-k="role">
            ${['君','臣','佐','使'].map(r => `<option ${it.role===r?'selected':''}>${r}</option>`).join('')}
          </select>
        </td>
        <td><input type="text" value="${it.prep||''}" data-i="${i}" data-k="prep" style="width:110px;"></td>
      </tr>`).join('');tb.querySelectorAll('input,select').forEach(el=>{el.onchange=()=>{const i=+el.getAttribute('data-i'),k=el.getAttribute('data-k');S.items[i][k]=el.value;};});}
function submit(){if(!S.zhengOk){alert('请先确认辨证。');return;}
if(S.items.length===0){alert('处方为空，请先选方或加味。');return;}
const zhengInput=($('tcm-zheng-input').value||'').trim();const faZhengInput=($('tcm-fazheng-input').value||S.case.treatment_principle||'').trim();const hits=window.TCMEngine.check({case:S.case,zhengInput,faZhengInput,formulaName:S.selectedFormula?S.selectedFormula.name:'',formulaCode:S.selectedFormula?S.selectedFormula.code:'',herbs:S.items});const review=window.TCMEngine.score(hits);renderReport(review,hits,{zhengInput,faZhengInput});saveHistory(review,hits);showView('view-tcm-report');}
function renderReport(review,hits,ctx){const arc=$('tcm-score-arc');const C=326.7;arc.style.strokeDashoffset=C-C*review.total/100;$('tcm-r-score').textContent=review.total;const grade=review.total>=85?'优秀':review.total>=70?'良好':review.total>=60?'合格':'需加强';$('tcm-r-grade').textContent=grade;$('tcm-r-meta').textContent=`${S.patient.name} · ${S.case.name || ''} · ${new Date().toLocaleString()}`;$('tcm-dim-grid').innerHTML=Object.values(review.dims).map(d=>{const verdict=d.hits.some(h=>h.severity==='error')?'error':d.hits.some(h=>h.severity==='warn')?'warn':'pass';return`
      <div class="dim-card tcm-dim ${verdict}">
        <div class="dim-name">${d.name}</div>
        <div class="dim-bar"><div class="dim-fill" style="width:${d.score/d.weight*100}%"></div></div>
        <div class="dim-num">${Math.round(d.score)}/${d.weight}</div>
      </div>`;}).join('');$('tcm-cnt-err').textContent=review.errorCount;$('tcm-cnt-warn').textContent=review.warnCount;$('tcm-cnt-pass').textContent=Math.max(0,hits.length-review.errorCount-review.warnCount);$('tcm-hit-list').innerHTML=hits.length===0?'<div class="hit-item pass">✅ 未命中错误规则</div>':hits.map(h=>`
        <div class="hit-item ${h.severity}">
          <b>[${h.rule_id}] ${h.title}</b><br>
          <span class="muted">${h.message}</span><br>
          ${h.suggestion ? `<span class="sug">💡 ${h.suggestion}</span>` : ''}
        </div>`).join('');$('tcm-diff-box').innerHTML=`
      <div style="font-size:13px;line-height:1.9;">
        <p><b>参考证型：</b>${S.case.syndrome_differentiation || '-'}　<b>你辨证：</b>${ctx.zhengInput || '-'}</p>
        <p><b>参考治法：</b>${S.case.treatment_principle || '-'}　<b>你立法：</b>${ctx.faZhengInput || '-'}</p>
        <p><b>参考用方：</b>${S.case.reference_formula_code || '-'}　<b>你选方：</b>${S.selectedFormula ? S.selectedFormula.name : '未选'}</p>
        <p><b>参考药味：</b>${(S.case.reference_herbs || []).join('、') || '-'}</p>
        <p><b>你处方：</b>${S.items.map(i => `${i.name}${i.dose}`).join('，')}</p>
      </div>`;}
function saveHistory(review,hits){const arr=JSON.parse(localStorage.getItem('rx-profile-history')||'[]');arr.unshift({t:Date.now(),total:review.total,module:'中医汉方',disease:S.case.name||'',disease_code:S.case.code||'',radar:{format:review.dims.zheng.score/review.dims.zheng.weight*100,match:review.dims.formula.score/review.dims.formula.weight*100,dose:review.dims.dosage.score/review.dims.dosage.weight*100,route:review.dims.fazheng.score/review.dims.fazheng.weight*100,compat:review.dims.compat.score/review.dims.compat.weight*100,special:80,ess:80,abx:80}});localStorage.setItem('rx-profile-history',JSON.stringify(arr.slice(0,20)));const errors=hits.filter(h=>h.severity==='error');const warns=hits.filter(h=>h.severity==='warn');if(errors.length||warns.length){const m=JSON.parse(localStorage.getItem('rx-mistakes')||'[]');m.unshift({t:Date.now(),module:'中医汉方',disease:S.case.name||'',score:review.total,errors:errors.map(e=>({rule_id:e.rule_id,title:e.title,message:e.message,suggestion:e.suggestion})),warns:warns.map(w=>({rule_id:w.rule_id,title:w.title,message:w.message}))});localStorage.setItem('rx-mistakes',JSON.stringify(m.slice(0,100)));}}
function pinyinMatch(query,pinyin){if(!query)return true;const q=query.toLowerCase();const p=(pinyin||'').toLowerCase();if(!p)return false;if(p.indexOf(q)>=0)return true;let i=0;for(let j=0;j<p.length&&i<q.length;j++){if(p[j]===q[i])i++;}
return i===q.length;}
function openHerbLib(){const modal=$('modal-herb-lib');if(!modal)return;const sel=$('herb-lib-category');if(sel&&sel.options.length<=1){const cats=Array.from(new Set(S.herbs.map(h=>h.category||'未分类'))).sort();sel.innerHTML='<option value="">全部分类</option>'+
cats.map(c=>`<option value="${c}">${c}</option>`).join('');}
$('herb-lib-count').textContent=`（共 ${S.herbs.length} 味）`;$('herb-lib-search').value='';$('herb-lib-category').value='';renderHerbLibGrid();$('herb-lib-detail').classList.add('hidden');modal.classList.remove('hidden');setTimeout(()=>{const s=$('herb-lib-search');if(s)s.focus();},50);}
function closeHerbLib(){const modal=$('modal-herb-lib');if(modal)modal.classList.add('hidden');}
function renderHerbLibGrid(){const kw=($('herb-lib-search').value||'').trim().toLowerCase();const cat=$('herb-lib-category').value;const grid=$('herb-lib-grid');const list=S.herbs.filter(h=>{if(cat&&h.category!==cat)return false;if(!kw)return true;if(h.name.toLowerCase().indexOf(kw)>=0)return true;return pinyinMatch(kw,h.pinyin);});$('herb-lib-count').textContent=`（${list.length} / ${S.herbs.length} 味）`;if(list.length===0){grid.innerHTML='<div class="herb-lib-empty">未找到匹配中药，换个关键词试试</div>';return;}
grid.innerHTML=list.map(h=>`
      <div class="herb-lib-chip" data-name="${h.name}">
        ${h.name}
        <small>${h.nature || ''}${h.taste || ''}</small>
      </div>`).join('');grid.querySelectorAll('.herb-lib-chip').forEach(el=>{el.onclick=()=>{grid.querySelectorAll('.herb-lib-chip').forEach(c=>c.classList.remove('active'));el.classList.add('active');showHerbDetail(el.getAttribute('data-name'));};});}
function showHerbDetail(name){const h=S.herbs.find(x=>x.name===name);if(!h)return;const box=$('herb-lib-detail');const arr=a=>Array.isArray(a)?(a.length?a.join('、'):'—'):(a||'—');box.innerHTML=`
      <h4 class="hd-title">${h.name}</h4>
      <div class="hd-meta">${h.category || ''} · 常用量 ${h.dose_range || '—'} · 参考价 ${h.price_yuan || '—'} 元/10g</div>
      <div class="hd-row"><b>性味归经：</b>${h.nature || ''} ${h.taste || ''}，归 ${h.meridian || '—'}</div>
      <div class="hd-row"><b>功效：</b>${h.functions || '—'}</div>
      <div class="hd-row"><b>主治：</b>${arr(h.indications)}</div>
      <div class="hd-row"><b>使用注意：</b>${arr(h.contraindications)}</div>
      ${h.incompatibility && h.incompatibility !== '无' ? `<div class="hd-warn">⚠️ 配伍禁忌：${h.incompatibility}</div>` : ''}
      ${h.note ? `<div class="hd-row"style="margin-top:8px;color:#94a3b8;font-size:12px;">📝 ${h.note}</div>` : ''}
    `;box.classList.remove('hidden');}
function bindEvents(){bindTabs();$('tcm-btn-new').onclick=newCase;$('tcm-btn-zheng-check').onclick=checkZheng;$('tcm-btn-back-home').onclick=()=>showView('view-tcm-home');$('tcm-btn-open-rx').onclick=openRx;$('tcm-btn-back-case').onclick=()=>showView('view-tcm-case');$('tcm-btn-print').onclick=()=>window.print();$('tcm-btn-submit').onclick=submit;$('tcm-report-home').onclick=()=>showView('view-tcm-home');$('tcm-btn-retry').onclick=()=>{showView('view-tcm-home');newCase();};$('tcm-formula-search').oninput=e=>renderFormulaList(e.target.value);$('tcm-herb-search').oninput=e=>renderHerbList(e.target.value);$('tcm-formula-select').onchange=e=>{const f=S.formulas.find(x=>x.name===e.target.value);if(f)selectFormula(f);};$('tcm-btn-herb-lib').onclick=openHerbLib;$('herb-lib-close').onclick=closeHerbLib;$('modal-herb-lib').addEventListener('click',e=>{if(e.target===$('modal-herb-lib'))closeHerbLib();});$('herb-lib-search').oninput=renderHerbLibGrid;$('herb-lib-category').onchange=renderHerbLibGrid;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('modal-herb-lib').classList.contains('hidden'))closeHerbLib();});}
document.addEventListener('DOMContentLoaded',function(){bindEvents();boot();});})();